-- EduSmart fresh Supabase schema
-- School tenants
-- Generated from src/data. Replaces only tables in schema edusmart.
-- Nested objects and mixed lists are jsonb. Plain lists are Postgres arrays.
-- Demo passwords from src/data are included. Row level security is on and has no policies,
-- so the anon API cannot read these tables. The SQL editor and service_role can.
begin;
create schema if not exists "edusmart";
grant usage on schema "edusmart" to postgres, service_role, authenticated, anon;

-- src/data/tenantsData.ts :: INITIAL_TENANTS (6 rows)
drop table if exists "edusmart"."tenants" cascade;
create table "edusmart"."tenants" (
  "id" text not null,
  "name" text not null,
  "short_name" text not null,
  "motto" text not null,
  "code" text not null,
  "logo_url" text not null,
  "crest_icon" text not null,
  "theme_color" text not null,
  "badge_color_class" text not null,
  "header_bg_class" text not null,
  "domain" text not null,
  "address" text not null,
  "city" text not null,
  "county" text not null,
  "phone" text not null,
  "email" text not null,
  "principal_name" text not null,
  "principal_title" text not null,
  "registration_number" text not null,
  "curriculum" text not null,
  "established_year" bigint not null,
  "grade_levels" text not null,
  "term" text not null,
  "academic_year" text not null,
  "total_students" bigint not null,
  "total_faculty" bigint not null,
  "total_classes" bigint not null,
  "attendance_today" bigint not null,
  "status" text not null,
  "plan" text not null,
  "expiry_date" text not null,
  "tagline_notes" text not null,
  "hero_title" text not null,
  "hero_subtitle" text not null,
  "curriculum_badge_text" text not null,
  "portal_card_badge" text not null,
  "hero_media_type" text,
  "hero_image_url" text,
  "hero_video_url" text,
  "hero_video_poster" text,
  "hero_video_badge" text,
  "print_header_theme" text not null,
  "print_footer_notes" text not null,
  "print_watermark_text" text not null,
  "primary_color_hex" text not null,
  "accent_color_hex" text not null,
  primary key ("id")
);
